import * as cloud from './cloud-store.js';
import * as team from './team-store.js?team=20261110b';
import {editable,safeTeamIcon,validateProposal} from './team-model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user,isOwner=false,snapshot,selected,proposedIcon='',pendingId,epoch=0;
const field=k=>$('#proposal-form').elements.namedItem(k),message=s=>$('#message').textContent=s;
const draftKey=()=>`hoek-team-draft:${user?.uid||''}`;
async function action(button,fn){button.disabled=true;try{await fn()}catch(e){message(e.code==='permission-denied'?'אין הרשאה לפעולה. ודאו שהמייל אושר ושהרשאות הצוות הותקנו.':e.message)}finally{button.disabled=false}}
function tab(name){for(const n of ['ribbon','proposals','members'])$('#'+n).hidden=n!==name;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>action(b,async()=>{tab(b.dataset.tab);if(b.dataset.tab==='proposals')await showProposals();if(b.dataset.tab==='members')await showMembers()}));
async function load(){const e=epoch;const s=await team.loadSnapshot();if(e!==epoch)return;snapshot=s;$('#version').textContent=`Ribbon ${s.packageVersion} · פרסום ${s.revision}`;renderRibbon();}
function path(n){const labels=[],seen=new Set;let p=snapshot.nodes.find(x=>x.id===n.parent);while(p&&!seen.has(p.id)){seen.add(p.id);labels.unshift(p.label);p=snapshot.nodes.find(x=>x.id===p.parent)}return labels.join(' / ')||'רעיונות';}
function renderRibbon(){if(!snapshot)return;const q=$('#search').value.trim().toLowerCase();const buttons=snapshot.nodes.filter(n=>n.type==='button'&&(!q||(n.label+' '+n.tooltip).toLowerCase().includes(q)));$('#ribbon-content').innerHTML=buttons.length?`<div class="tools-grid">${buttons.map(n=>`<button class="tool" data-node="${esc(n.id)}">${safeTeamIcon(n.icon)?`<img src="${esc(n.icon)}" alt="">`:''}<b>${esc(n.label)}</b><small>${esc(path(n))}</small><small>${isOwner?'צפייה':'הצעת שינוי ↗'}</small></button>`).join('')}</div>`:'<p>אין כלים מתאימים לחיפוש.</p>';document.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{if(isOwner){message('עריכה ישירה נעשית בסטודיו הראשי. הצעות העובדים מופיעות בלשונית הצעות.');return}openEditor(snapshot.nodes.find(n=>n.id===b.dataset.node))});}
$('#search').oninput=renderRibbon;
function openEditor(n,draft){selected=n?structuredClone(n):null;pendingId=draft?.id||crypto.randomUUID();proposedIcon=draft?.icon||'';$('#proposal-form').reset();$('#editor-title').textContent=n?'הצעת שינוי · '+n.label:'רעיון לכלי חדש';
 for(const k of ['label','tooltip','priority','order'])field(k).value=draft?.values?.[k]??(k==='order'?(n?.order||0)+1:n?.[k]|| (k==='priority'?'normal':''));
 field('parent').innerHTML='<option value="backlog">רעיונות להמשך</option>'+snapshot.nodes.filter(x=>['panel','stack','dropdown'].includes(x.type)).map(x=>`<option value="${esc(x.id)}">${esc(path(x)+' / '+x.label)}</option>`).join('');field('parent').value=draft?.values?.parent||n?.parent||'backlog';field('comment').value=draft?.values?.comment||'';field('parent').disabled=field('order').disabled=!n;$('#draft-status').textContent=draft?'טיוטה אישית שוחזרה. טרם נשלחה.':'';$('#proposal-editor').showModal();}
function saveDraft(){if(!user)return;const values=Object.fromEntries(['label','tooltip','priority','parent','order','comment'].map(k=>[k,field(k).value]));try{localStorage.setItem(draftKey(),JSON.stringify({id:pendingId,selected,revision:snapshot.revision,values,icon:proposedIcon}));$('#draft-status').textContent='טיוטה אישית נשמרה במכשיר · לא נשלחה'}catch{$('#draft-status').textContent='אין מקום לשמירת טיוטה במכשיר'}}
$('#proposal-form').oninput=saveDraft;
field('image').onchange=async()=>{const f=field('image').files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>100000){message('יש לבחור תמונת PNG/JPG/WebP עד 100KB');field('image').value='';return}proposedIcon=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});saveDraft();};
$('#new-idea').onclick=()=>openEditor(null);
$('#proposal-editor [data-close]').onclick=()=>$('#proposal-editor').close();
$('#proposal-form').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{const changes={};for(const k of ['label','tooltip','priority'])if(!selected||field(k).value!==(selected[k]??''))changes[k]=field(k).value;if(proposedIcon)changes.icon=proposedIcon;if(selected&&(field('parent').value!==selected.parent||+field('order').value-1!==selected.order)){changes.parent=field('parent').value;changes.order=+field('order').value-1}const p=validateProposal({kind:selected?'edit':'idea',nodeId:selected?.id||'',base:selected?Object.fromEntries([...editable,'parent','order'].map(k=>[k,selected[k]??''])):{},changes,comment:field('comment').value});await team.submitProposal(p,snapshot.revision,pendingId);localStorage.removeItem(draftKey());$('#proposal-editor').close();message('ההצעה נשלחה לעדי וממתינה לאישור. הסרגל הראשי לא השתנה.');tab('proposals');await showProposals();});};
function displayValue(k,v){if(k==='icon')return safeTeamIcon(v)?`<img src="${esc(v)}" alt="אייקון">`:'ללא אייקון';if(k==='parent')return esc(snapshot?.nodes.find(n=>n.id===v)?.label||v);if(k==='order')return esc(Number(v)+1);return esc(v);}
async function showProposals(){const e=epoch,rows=await team.listProposals();if(e!==epoch)return;$('#proposals-title').textContent=isOwner?'הצעות שממתינות לאישורך':'ההצעות שלי';$('#proposal-list').innerHTML=rows.length?rows.map(r=>{let p;try{p=validateProposal(JSON.parse(r.payload))}catch{return `<article class="proposal"><h3>הצעה בפורמט לא נתמך</h3><p>${esc(r.authorEmail)}</p>${isOwner?`<button data-reject="${esc(r.id)}">דחייה</button>`:''}</article>`}return `<article class="proposal"><h3>${esc(p.kind==='idea'?'רעיון חדש':snapshot?.nodes.find(n=>n.id===p.nodeId)?.label||p.nodeId)}</h3><p>${esc(r.authorEmail)} · ${esc({pending:'ממתינה',approved:'אושרה',rejected:'נדחתה'}[r.status])} · בסיס ${r.baseRevision}</p><p>${esc(p.comment)}</p>${Object.entries(p.changes).map(([k,v])=>`<b>${esc({label:'שם',tooltip:'תיאור',priority:'עדיפות',icon:'אייקון',parent:'קבוצה',order:'מיקום'}[k]||k)}</b><div class="diff"><div><small>בזמן ההצעה</small><pre>${displayValue(k,p.base[k]??'')}</pre></div><div><small>מוצע</small><pre>${displayValue(k,v)}</pre></div></div>`).join('')}${r.reviewNote?`<p>תשובת עדי: ${esc(r.reviewNote)}</p>`:''}${isOwner?`<label>הערה למציע<textarea data-review="${esc(r.id)}" maxlength="6000"></textarea></label><button class="primary" data-approve="${esc(r.id)}">אישור והחלה בתכנון הראשי</button> <button data-reject="${esc(r.id)}">דחייה</button>`:''}</article>`}).join(''):'<p>אין הצעות להצגה.</p>';if(rows.length===100)$('#proposal-list').insertAdjacentHTML('beforeend','<p>מוצגות עד 100 הצעות. לאחר טיפול, רעננו לקבלת הבאות.</p>');for(const b of document.querySelectorAll('[data-approve],[data-reject]'))b.onclick=()=>action(b,async()=>{const id=b.dataset.approve||b.dataset.reject,note=[...document.querySelectorAll('[data-review]')].find(x=>x.dataset.review===id)?.value||'';await team.decide(id,!!b.dataset.approve,note);message(b.dataset.approve?'ההצעה אושרה ונשמרה בתכנון הראשי בענן. אפשר לפרסם לצוות את התכנון המעודכן בלשונית מורשים ושיתוף.':'ההצעה נדחתה. התכנון לא השתנה.');await showProposals()});}
async function showMembers(){const rows=await team.listMembers();$('#member-list').innerHTML=rows.map(r=>`<div class="member-row"><span dir="ltr">${esc(r.email)}</span><span>${r.active?'פעיל':'גישה בוטלה'}</span><button data-member="${esc(r.email)}" data-active="${!r.active}">${r.active?'ביטול גישה':'החזרת גישה'}</button></div>`).join('');document.querySelectorAll('[data-member]').forEach(b=>b.onclick=()=>action(b,async()=>{await team.setMember(b.dataset.member,b.dataset.active==='true');await showMembers()}));}
$('#member-form').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{await team.setMember($('#member-email').value,true);$('#member-email').value='';await showMembers();message('המייל נוסף. העובד יכול לפתוח את פורטל הצוות ולבקש קישור כניסה.')})};
$('#publish').onclick=e=>action(e.currentTarget,async()=>{const r=await team.publish();await load();message(`פורסמה לצוות גרסת תכנון ${r}. ההערות הפרטיות לא נכללו.`)});
$('#refresh').onclick=e=>action(e.currentTarget,async()=>{await team.access();await load();if(!$('#proposals').hidden)await showProposals();message('התצוגה עודכנה מהענן')});
$('#logout').onclick=e=>action(e.currentTarget,async()=>{await cloud.logout()});
$('#google').onclick=e=>action(e.currentTarget,()=>cloud.login());
if(team.hasEmailLink()){$('#email-action').textContent='אימות וכניסה';$('#email').value=sessionStorage.getItem('hoek-team-email')||'';message('להשלמת הכניסה, אשרו את כתובת המייל שאליה נשלח הקישור.')}
$('#login-form').onsubmit=e=>{e.preventDefault();action(e.submitter,async()=>{if(team.hasEmailLink())await team.finishLink($('#email').value);else{await team.sendLink($('#email').value);message('קישור הכניסה נשלח. בדקו גם בתיקיית דואר זבל.')}})};
cloud.authChanged(async u=>{epoch++;user=u;snapshot=null;$('#ribbon-content').replaceChildren();$('#proposal-list').replaceChildren();$('#member-list').replaceChildren();$('#proposal-editor').close();$('#workspace').hidden=true;$('#login').hidden=!!u;$('#logout').hidden=!u;$('#identity').textContent=u?.email||'';if(!u)return;try{const e=epoch,a=await team.access();if(e!==epoch)return;isOwner=a.owner;$('#members-tab').hidden=!isOwner;$('#new-idea').hidden=isOwner;$('#workspace').hidden=false;message('');try{await load()}catch(err){if(isOwner){tab('members');message('יש לפרסם את התכנון לצוות כדי להתחיל. '+err.message);await showMembers()}else throw err}if(!isOwner){let draft;try{draft=JSON.parse(localStorage.getItem(draftKey()))}catch{}if(draft&&draft.revision===snapshot.revision)openEditor(draft.selected,draft);else if(draft)message('נשמרה טיוטה מגרסה ישנה. התכנון עודכן; יש להכין הצעה חדשה כדי למנוע דריסת שינויים.')}}catch(e){message(e.code==='permission-denied'?'הגישה לצוות אינה זמינה למייל הזה, או שהרשאות הצוות טרם הותקנו.':e.message)}});
